validator:
function validate(input) {
  const [{ Activity = [] }] = input;
  const seen = new Set();
  for (const [playerId, deviceId, eventDate, gamesPlayed] of Activity) {
    if (playerId === null || deviceId === null) return 'Every row needs a player_id and a device_id.';
    if (typeof eventDate !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(eventDate)) return `event_date ${eventDate} must be a YYYY-MM-DD date.`;
    if (gamesPlayed === null || gamesPlayed < 0) return `games_played must be a non-negative number (player ${playerId}, ${eventDate}).`;
    const key = `${playerId}|${eventDate}`;
    if (seen.has(key)) return `Player ${playerId} has two rows on ${eventDate}.`;
    seen.add(key);
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const day = offset => new Date(Date.UTC(2016, 11, 28) + offset * 86400000).toISOString().slice(0, 10);
  // Small tables use 3 players and 8 dates around a year boundary, so players share dates and switch devices.
  const players = small ? 3 : 100, days = small ? 8 : 60, target = small ? Math.floor(rand() * 9) : 2000;
  const Activity = [], seen = new Set();
  for (let tries = 0; Activity.length < target && tries < target * 4; tries++) {
    const playerId = 1 + Math.floor(rand() * players);
    const eventDate = day(small ? Math.floor(rand() * days) : Math.floor(rand() * days) * 7);
    const key = `${playerId}|${eventDate}`;
    if (seen.has(key)) continue;
    seen.add(key);
    Activity.push([playerId, 1 + Math.floor(rand() * 3), eventDate, Math.floor(rand() * 7)]);
  }
  return [{ Activity }];
}
